CREATE TABLE IF NOT EXISTS "User" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,phone text NOT NULL,address text NOT NULL DEFAULT '',"passwordHash" text NOT NULL DEFAULT '',role text NOT NULL DEFAULT 'CUSTOMER' CHECK(role IN ('CUSTOMER','STAFF')),"manualRefillDays" integer,"createdAt" bigint NOT NULL,"passwordChangedAt" bigint);
CREATE TABLE IF NOT EXISTS "Cylinder" (id text PRIMARY KEY,"sizeKg" double precision NOT NULL UNIQUE,"pricePerKg" double precision NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS "Orders" (id text PRIMARY KEY,"customerId" text NOT NULL REFERENCES "User"(id),"cylinderId" text NOT NULL REFERENCES "Cylinder"(id),quantity integer NOT NULL CHECK(quantity>0),fulfilment text NOT NULL CHECK(fulfilment IN ('PICKUP','DELIVERY')),"deliveryAddress" text NOT NULL DEFAULT '',"totalPrice" double precision NOT NULL,status text NOT NULL DEFAULT 'PENDING',"createdAt" bigint NOT NULL,"readyAt" bigint,"readyEmailSentAt" bigint,"completedAt" bigint);
CREATE TABLE IF NOT EXISTS "Payment" (id text PRIMARY KEY,"orderId" text NOT NULL REFERENCES "Orders"(id),reference text NOT NULL UNIQUE,amount integer NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','SUCCESS','FAILED')),provider text NOT NULL DEFAULT 'PAYSTACK',"createdAt" bigint NOT NULL);
CREATE TABLE IF NOT EXISTS "AutomationLog" (id text PRIMARY KEY,type text NOT NULL,"orderId" text REFERENCES "Orders"(id),"customerId" text REFERENCES "User"(id),status text NOT NULL CHECK(status IN ('SENT','FAILED')),error text,"createdAt" bigint NOT NULL);
CREATE TABLE IF NOT EXISTS "AuthThrottle" (email text PRIMARY KEY,attempts integer NOT NULL,"resetAt" bigint NOT NULL,"blockedUntil" bigint);
CREATE TABLE IF NOT EXISTS "PasswordResetToken" ("tokenHash" text PRIMARY KEY,"userId" text NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,"expiresAt" bigint NOT NULL,"createdAt" bigint NOT NULL);
CREATE TABLE IF NOT EXISTS "CustomerRefillEstimate" ("customerId" text NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,"sizeKg" double precision NOT NULL,days integer NOT NULL CHECK(days BETWEEN 7 AND 90),"updatedAt" bigint NOT NULL,PRIMARY KEY("customerId","sizeKg"));
CREATE INDEX IF NOT EXISTS orders_customer_created ON "Orders"("customerId","createdAt" DESC);
CREATE INDEX IF NOT EXISTS orders_status_created ON "Orders"(status,"createdAt");
CREATE INDEX IF NOT EXISTS payment_order ON "Payment"("orderId");
